      name.hashCode ^
      valueType.hashCode ^
      min.hashCode ^
      max.hashCode ^
      allowed.hashCode ^
      labels.hashCode ^
      scale.hashCode ^
      valueOffset.hashCode ^
      unit.hashCode ^
      default_.hashCode ^
      auto.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ParameterDto &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          valueType == other.valueType &&
          min == other.min &&
          max == other.max &&
          allowed == other.allowed &&
          labels == other.labels &&
          scale == other.scale &&
          valueOffset == other.valueOffset &&
          unit == other.unit &&
          default_ == other.default_ &&
          auto == other.auto;
}

